INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ovb21-required-missing', 18, 'func', 'Обязательные сети, которых нет на хосте', 'Сеть, подключённая к кластеру (network → cluster), обязательна, если в её params нет required или required не равно False. Хост должен иметь все обязательные сети своего кластера: связь network → host. Напишите функцию required_missing(board): для каждого хоста, который входит в кластер, верните отсортированный список id обязательных сетей его кластера, не назначенных на хост. В словаре должны быть все такие хосты, в том числе с пустым списком. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def required_missing(board):
    pass
