INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ovb21-mgmt-path', 19, 'func', 'Путь менеджера до хоста', 'Менеджер достаёт до хоста по сети управления. Напишите функцию management_path(board, host): найдите менеджера, который управляет дата-центром хоста (engine → data_center; дата-центр хоста — дата-центр его кластера), и сеть с params.role равным "management", у которой есть связи engine → network и network → host. Верните [id менеджера, id сети] или None, если пути нет. Если путей несколько — первый менеджер и первая сеть в порядке связей в edges. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def management_path(board, host):
