INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ovb21-host-status', 20, 'func', 'Статус хоста по схеме', 'Соберите всё вместе. Напишите функцию host_statuses(board): для каждого хоста верните статус — "No cluster", если хост не входит в кластер или кластер не входит в дата-центр; иначе "NonResponsive", если нет пути менеджера до хоста (задача про путь менеджера); иначе "NonOperational", если на хост не назначена обязательная сеть его кластера или он не видит домен, подключённый к его дата-центру; иначе "Up". Верните словарь id хоста → статус для всех хостов. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def host_statuses(board):
    pass
