INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 21, 'ovb21-unplugged', 22, 'func', 'Куда не подключить сетевую карту машины', 'Виртуальная сетевая карта машины включена в сеть связью network → vm. Она работает, только если эта сеть назначена на хост, где стоит машина (host → vm и network → host). Напишите функцию unplugged(board, vm): верните None, если машина не стоит ни на каком хосте; иначе отсортированный список id сетей её сетевых карт, не назначенных на хост машины. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def unplugged(board, vm):
    pass
